const manifest = $json;
const now = Date.now();
const state = $getWorkflowStaticData('global');
state.publishedIds ??= {};
for (const prior of (manifest.items || [])) {
  if (prior.alreadyPublished || prior.status === 'published' || prior.platformPostId) {
    state.publishedIds[prior.id] ??= { platformPostId: prior.platformPostId || null, publishedAt: prior.publishedAt || null };
  }
}
const due = (Array.isArray(manifest.items) ? manifest.items : [])
  .filter((candidate) => candidate.status === 'scheduled' && candidate.approvalStatus === 'approved' && Date.parse(candidate.scheduledAt || 0) <= now && !candidate.alreadyPublished && !candidate.platformPostId && !candidate.platformPermalink && !state.publishedIds[candidate.id])
  .sort((a, b) => Date.parse(a.scheduledAt) - Date.parse(b.scheduledAt));
const item = due[0] || null;
const blockers = [];
if (manifest.killSwitch !== false) blockers.push('GLOBAL_KILL_SWITCH_ON');
if (manifest.automationMode !== 'production') blockers.push('NOT_PRODUCTION_MODE');
if (manifest.destination?.platform !== 'facebook') blockers.push('WRONG_PLATFORM');
if (manifest.destination?.pageId !== '111009258047115') blockers.push('PAGE_NOT_ALLOWLISTED');
if (!/^v\d+\.\d+$/.test(manifest.destination?.graphApiVersion || '')) blockers.push('INVALID_GRAPH_API_VERSION');
if (!item) blockers.push('NO_DUE_APPROVED_ITEM');
if (item) {
  const mediaType = item.mediaType === 'photo' ? 'image' : item.mediaType;
  if (!item.reviewerId || !item.approvalTimestamp) blockers.push('MISSING_APPROVAL_AUDIT');
  if (item.approvalExpiresAt && Date.parse(item.approvalExpiresAt) <= now) blockers.push('APPROVAL_EXPIRED');
  if (!item.captionMyanmar?.trim()) blockers.push('EMPTY_CAPTION');
  if (!item.mediaUrl?.startsWith('https://child.acegroup.com.mm/')) blockers.push('MEDIA_NOT_ON_APPROVED_HOST');
  if (!item.mediaSha256) blockers.push('MISSING_MEDIA_HASH');
  if (!item.approvedContentHash) blockers.push('MISSING_APPROVED_HASH');
  if (!['image', 'reel'].includes(mediaType)) blockers.push('UNSUPPORTED_MEDIA_TYPE');
  if (mediaType === 'reel' && !/^https:\/\/child\.acegroup\.com\.mm\/.+\.mp4(?:\?.*)?$/i.test(item.mediaUrl || '')) blockers.push('REEL_MUST_BE_HOSTED_MP4');
  if (item.riskLevel === 'high' && !item.clinicalApprovalId) blockers.push('MISSING_CLINICAL_APPROVAL');
}
return [{ json: { ...(item || {}), destinationPageId: manifest.destination?.pageId, graphApiVersion: manifest.destination?.graphApiVersion, automationMode: manifest.automationMode, killSwitch: manifest.killSwitch, eligible: blockers.length === 0, blockers } }];

const item = $('Validate Kill Switch Approval and Duplicate Gates').item.json;
const response = $json;
if (item.mediaType === 'reel' && response.success !== true) throw new Error('META_REEL_PUBLISH_FAILED');
const platformPostId = item.mediaType === 'reel' ? $('Start Facebook Reel Upload - CREDENTIAL REQUIRED').item.json.video_id : (response.post_id || response.id);
if (!platformPostId) throw new Error('META_RESPONSE_MISSING_POST_ID');
const state = $getWorkflowStaticData('global');
state.publishedIds ??= {};
state.publishedIds[item.id] = { platformPostId, publishedAt: new Date().toISOString(), approvedContentHash: item.approvedContentHash, mediaType: item.mediaType };
return [{ json: { result: 'PUBLISHED', postId: item.id, platformPostId, mediaType: item.mediaType, publishedAt: state.publishedIds[item.id].publishedAt } }];
